WITH base AS (SELECT id, order_id, carrier, shipped_date, cost, status, DATE_ADD(delivered_date, 12) AS delivered_date_plus_12d, COALESCE(carrier, 'OTHER') AS carrier_filled FROM shipments WHERE MONTH(shipped_date) IN (3, 4, 6) AND shipped_date > TO_DATE('2023-03-20')), with_windows AS (SELECT id, carrier, shipped_date, cost, status, ROUND(cost / SUM(cost) OVER (PARTITION BY order_id), 4) AS cost_share, AVG(cost) OVER w_ordered AS cost_avg_3 FROM base WHERE cost < 92 WINDOW w_ordered AS (PARTITION BY carrier, order_id ORDER BY delivered_date_plus_12d, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW)), metrics AS (SELECT id, cost, SUM(cost_share) OVER w_hist AS status_sum_cost_share, FIRST_VALUE(cost_avg_3, TRUE) OVER (ORDER BY cost, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_cost_avg_3, AVG(cost) OVER (ORDER BY cost_share, id ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS cost_avg_6, STDDEV_SAMP(cost) OVER w_hist AS status_stddev_samp_cost FROM with_windows WINDOW w_hist AS (PARTITION BY status)), with_windows_shipments AS (SELECT id, cost, status_sum_cost_share, first_known_cost_avg_3, LEAD(cost_avg_6) OVER (ORDER BY status_sum_cost_share, id) AS next_cost_avg_6, LAG(cost_avg_6) OVER (ORDER BY status_sum_cost_share, id) AS prev_cost_avg_6, LAG(status_sum_cost_share) OVER (ORDER BY status_sum_cost_share, id) AS prev_status_sum_cost_share, ROW_NUMBER() OVER (ORDER BY status_sum_cost_share, id) AS row_seq FROM metrics) SELECT id, status_sum_cost_share, first_known_cost_avg_3, next_cost_avg_6, prev_cost_avg_6, prev_status_sum_cost_share, row_seq FROM with_windows_shipments ORDER BY id LIMIT 20
